// Wallapop - verificar si el anuncio sigue en pie.
//
// Mismo endpoint que el enriquecedor, pero aqui solo interesa una cosa: si
// existe. Un 404 es una respuesta limpia y barata -unos 60 ms-, sin HTML que
// interpretar ni heuristicas de redireccion a la home.

const out = $input.item.json;
const oferta = $('Loop: oferta por oferta').item.json;
const id = oferta.id;
// Como consta ahora. Sirve para distinguir un cambio de estado de una simple
// reconfirmacion, y no mover updated_at cuando no ha pasado nada.
const eraActiva = oferta.is_active !== false;

const status = Number(out.statusCode || 0);

function esc(v) { if (v === null || v === undefined || v === '') return null; return "'" + String(v).replace(/'/g, "''") + "'"; }

// Vendida o retirada. Es el unico veredicto que da de baja.
//
// Si ya constaba inactiva no se toca updated_at: se limita a rotar la fecha de
// comprobacion. Antes se reescribia cada dia, y eso borraba el unico rastro que
// queda de CUANDO se cayo el anuncio -no hay columna para esa fecha- porque lo
// dejaba pareciendo que se habia caido hoy.
if (status === 404 || status === 410) {
  const sets = eraActiva
    ? 'is_active=FALSE, last_checked_at=NOW(), updated_at=NOW()'
    : 'last_checked_at=NOW()';
  return [{ json: { sql: 'UPDATE moveadvisor_market_offers SET ' + sets + ' WHERE id=' + esc(id), count: 1, veredicto: 'vendida' } }];
}

// Sigue publicada. Si constaba inactiva se resucita -asi se corrige sola una
// que se diera por muerta por error-; si ya constaba activa, solo se rotan las
// fechas.
//
// Se toca last_seen_at, y no es un detalle: es lo que convierte esa columna en
// la fecha de baja. El scraper solo lee las 40 paginas de mas recientes, asi
// que no vuelve a ver casi ninguna oferta y last_seen_at se quedaba diciendo
// cuando nos la cruzamos, no cuando dejo de estar publicada -en Wallapop las
// activas y las inactivas tenian el mismo rango de fechas, indistinguibles.
// Refrescandola aqui pasa a significar 'la ultima vez que comprobamos que
// seguia en pie', y en una oferta caida se congela sola en su ultimo dia bueno.
// Como se pasa tres veces al dia, la fecha de baja sale con unas ocho horas de
// margen. No hace falta columna nueva.
//
// Con un matiz que conviene no olvidar: la ficha no dice si esta reservada -ese
// campo solo sale en el buscador, y ni ahi aparece-, asi que un coche reservado
// pero con el anuncio en pie cuenta aqui como vivo. Es lo que se puede saber.
if (status === 200) {
  const sets = eraActiva
    ? 'last_checked_at=NOW(), last_seen_at=NOW()'
    : 'is_active=TRUE, last_checked_at=NOW(), last_seen_at=NOW(), updated_at=NOW()';
  return [{ json: { sql: 'UPDATE moveadvisor_market_offers SET ' + sets + ' WHERE id=' + esc(id), count: 1, veredicto: 'viva' } }];
}

// 429, 5xx, timeout: no sabemos nada, asi que no se toca is_active. Solo se
// mueve last_checked_at para que la cola siga girando y no se atasque en esta
// oferta -es lo mismo que hace scripts/verify-liveness.js con las transitorias.
return [{ json: { sql: 'UPDATE moveadvisor_market_offers SET last_checked_at=NOW() WHERE id=' + esc(id), count: 1, veredicto: 'transitoria' } }];
